        body: JSON.stringify(schema)
      });
      console.log('Create collection status:', createRes.status);
      const createData = await createRes.json();
      console.log('Create collection response:', createData);
    }

    // 2. Seed documents
    const players = [
      { player_id: "p1", name: "Alice", score: 100 },
      { player_id: "p2", name: "Bob", score: 100 },
      { player_id: "p3", name: "Carol", score: 90 },
      { player_id: "p4", name: "Dave", score: 80 },
      { player_id: "p5", name: "Eve", score: 70 }
    ];

    for (const p of players) {
      const doc = { id: p.player_id, name: p.name, score: p.score };
      const docRes = await fetch(`${BASE_URL}/collections/leaderboard/documents?action=upsert`, {
        method: 'POST',
        headers: {
          'X-TYPESENSE-API-KEY': API_KEY,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(doc)
      });
      console.log(`Upsert ${p.player_id} status:`, docRes.status);
      const docData = await docRes.json();
      console.log(`Upsert ${p.player_id} response:`, docData);
    }

    // 3. Search documents
    const searchRes = await fetch(`${BASE_URL}/collections/leaderboard/documents/search?q=*&query_by=name&sort_by=score:desc,name:asc&per_page=250`, {
      headers: { 'X-TYPESENSE-API-KEY': API_KEY }
    });
    console.log('Search status:', searchRes.status);
    const searchData = await searchRes.json();
    console.log('Search results:', JSON.stringify(searchData, null, 2));

  } catch (err) {
    console.error('Error:', err);
  }
}

