<body>
    <h1>Realtime Leaderboard</h1>
    
    <div class="leaderboard-container">
        <table>
            <thead>
                <tr>
                    <th>Rank</th>
                    <th>Name</th>
                    <th>Score</th>
                </tr>
            </thead>
            <tbody id="leaderboard" data-testid="leaderboard">
                <!-- Rows will be dynamically loaded here -->
            </tbody>
        </table>
    </div>

    <div class="form-container">
        <h2>Update Score</h2>
        <form id="score-form">
            <div class="form-group">
                <label for="player-id">Player ID</label>
                <input type="text" id="player-id" data-testid="player-id-input" required placeholder="e.g. p1">
            </div>
            <div class="form-group">
                <label for="delta">Score Delta</label>
                <input type="number" id="delta" data-testid="delta-input" required placeholder="e.g. 10 or -5">
            </div>
            <button type="submit" id="submit-score" data-testid="submit-score">Submit Update</button>
        </form>
        <div id="error-msg" class="error-message"></div>
        <div id="success-msg" class="success-message"></div>
    </div>

    <script>
        const leaderboardBody = document.getElementById('leaderboard');
        const scoreForm = document.getElementById('score-form');
        const playerIdInput = document.getElementById('player-id');
        const deltaInput = document.getElementById('delta');
        const errorMsg = document.getElementById('error-msg');
        const successMsg = document.getElementById('success-msg');

        async function fetchLeaderboard() {
            try {
                const res = await fetch('/api/leaderboard');
                if (!res.ok) throw new Error('Failed to fetch leaderboard');
                const players = await res.json();
                renderLeaderboard(players);
            } catch (err) {
                console.error(err);
            }
        }

        function renderLeaderboard(players) {
            leaderboardBody.innerHTML = '';
            players.forEach(p => {
                const tr = document.createElement('tr');
                tr.setAttribute('data-player-id', p.player_id);
                
                const tdRank = document.createElement('td');
                tdRank.setAttribute('data-testid', 'rank');
                tdRank.textContent = p.rank;
                
                const tdName = document.createElement('td');
                tdName.setAttribute('data-testid', 'name');
                tdName.textContent = p.name;
                
                const tdScore = document.createElement('td');
                tdScore.setAttribute('data-testid', 'score');
                tdScore.textContent = p.score;
                
                tr.appendChild(tdRank);
                tr.appendChild(tdName);
                tr.appendChild(tdScore);
                
                leaderboardBody.appendChild(tr);
            });
        }

        scoreForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            errorMsg.style.display = 'none';
            successMsg.style.display = 'none';

            const player_id = playerIdInput.value.trim();
            const delta = parseInt(deltaInput.value, 10);

            if (!player_id) {
                showError('Player ID is required');
                return;
            }
            if (isNaN(delta)) {
                showError('Delta must be an integer');
                return;
            }

            try {
                const res = await fetch('/api/score', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ player_id, delta })
                });

                if (res.status === 404) {
                    showError(`Player ID "${player_id}" not found`);
                    return;
                }
                if (res.status === 400) {
                    showError('Invalid input data');
                    return;
                }
                if (!res.ok) {
                    showError('Server error occurred');
                    return;
                }

                const updatedPlayer = await res.json();
                showSuccess(`Updated ${updatedPlayer.name}'s score to ${updatedPlayer.score}`);
                
                // Clear inputs
                playerIdInput.value = '';
                deltaInput.value = '';

                // Immediately refresh leaderboard
                await fetchLeaderboard();
            } catch (err) {
                showError('Network error connecting to server');
            }
        });

        function showError(msg) {
            errorMsg.textContent = msg;
            errorMsg.style.display = 'block';
        }

        function showSuccess(msg) {
            successMsg.textContent = msg;
            successMsg.style.display = 'block';
        }

        // Initial fetch
        fetchLeaderboard();

        // Poll every 1 second
        setInterval(fetchLeaderboard, 1000);
    </script>
</body>
